def parse_args():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-dir",type=Path,default=Path("."))
    parser.add_argument("--open-html",action="store_true")
    return parser.parse_args()

def main():
    args=parse_args()
    output_dir=args.output_dir.expanduser().resolve()
    output_dir.mkdir(parents=True,exist_ok=True)
    html_path=output_dir/"graphify_all_9_models_datasets_v2.html"
    json_path=output_dir/"graphify_all_9_models_datasets_v2.json"
    html_path.write_text(HTML_CONTENT,encoding="utf-8")
    json_path.write_text(JSON_CONTENT+"\n",encoding="utf-8")
    print("Graphify v2 created successfully.")
    print(f"HTML: {html_path}")
    print(f"JSON: {json_path}")
    if args.open_html:webbrowser.open(html_path.as_uri())

if __name__=="__main__":main()
